css:
/* マーキー帯（中身は同じ span を2回分入れておく） */
.marquee{height:28px; background:#6ee87a; overflow:hidden; white-space:nowrap;
  display:flex; align-items:center}
.marquee>span{display:inline-block; padding-right:40px;
  animation:m 18s linear infinite}
@keyframes m{to{transform:translateX(-50%)}}

/* 写真ストリップ帯（余白ゼロで密着） */
.strip{display:grid; grid-template-columns:repeat(5,1fr); gap:2px; margin-bottom:0}
.strip img{width:100%; aspect-ratio:1/1.1; object-fit:cover; display:block}
.strip + section{margin-top:0}
